import {startup} from './startup.js';startup.skip();
// Isolated layout/interaction fixture. No API or game requests.
import {Resources} from './resources.js';import {ResourceTracker,resourcesModel} from './resources-model.js';import {FrameClock} from './frame-clock.js';import {Localization} from './i18n.js';import {PixiCrtOverlay} from './vfx/pixi-overlay.js';
const i18n=await Localization.load();i18n.apply();const clock=new FrameClock(30),tracker=new ResourceTracker(),options={surface:'nauvis',minutes:30};
document.querySelector('#link-text').textContent='ПРОВЕРОЧНЫЕ ДАННЫЕ';document.querySelector('#link-state').dataset.state='ready';document.querySelector('#vfx-status').textContent=i18n.text('vfx.on');const language=document.createElement('option');language.textContent=i18n.catalog.locales[0].name;document.querySelector('#language').append(language);let topic;
const names=['iron-ore','copper-ore','coal','stone','uranium-ore','crude-oil'];
for(let step=0;step<5;step++){const tick=1000+step*1200,chunks=[];for(const surface of ['nauvis','vulcanus'])for(let i=0;i<45;i++)for(let x=0;x<3;x++)for(let y=0;y<2;y++)chunks.push({surface,name:names[i%6],chunk_x:(i%9)*7+x-32,chunk_y:Math.floor(i/9)*6+y-12,amount:i===0?Math.max(0,6000-step*1000):50000+i*10000-step*(i%3?100:0),tiles:64,infinite:i%6===5,sampled_at_tick:tick});topic={tick,written_at:new Date().toISOString(),payload:{coverage:{discovery_complete:true,resource_chunks:chunks.length},data:{chunks}}};tracker.accept(topic);}
const view=new Resources(i18n,patch=>{Object.assign(options,patch);render();});function render(){window.fixtureModel=resourcesModel({resources:topic},options,tracker);const {searchNames,...normalized}=window.fixtureModel.options;Object.assign(options,normalized);view.render(window.fixtureModel,{status:{topics:{resources:topic}}},()=>1);}
window.fixtureEmpty=()=>{tracker.clear();topic={...topic,tick:9000,payload:{coverage:{discovery_complete:true},data:{chunks:[]}}};render();};
for(const main of document.querySelectorAll('main'))main.hidden=main.id!=='resources-screen';document.querySelector('.console').dataset.view='resources';for(const b of document.querySelectorAll('.screen-nav button')){b.disabled=b.id!=='nav-resources';if(b.id==='nav-resources')b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}render();const profile=await(await fetch('./vfx/crt-profile.json')).json();const effect=await PixiCrtOverlay.create(document.querySelector('.console'),profile,clock);effect.setEnabled(true);effect.nextGlitch=performance.now()+3600000;window.fixtureReady=true;
